// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Scenario: user deposits 1 wei, then withdraws all (first withdrawal succeeds).
        // In the correct contract, the credit is reset to 0 after the first withdrawal.
        // In the buggy version, the credit remains 1, allowing a second withdrawal.
        address user = address(0x123);
        vm.deal(user, 1 wei);
        vm.prank(user);
        c.deposit{value: 1 wei}();
        vm.prank(user);
        c.withdrawAll(); // first withdrawal
        // Check the credit of user; in correct contract it should be 0, in buggy it's still 1.
        // Since credit is public, we can read it via the auto-generated getter.
        uint creditAfter = c.credit(user);
        // The correct contract has credit = 0; the buggy one has credit = 1.
        assertTrue(creditAfter == 0, "credit should be 0 after withdrawal in correct contract");
    }
}

