// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 10 ether);

        // deposit 1 wei
        vm.prank(user);
        c.deposit{value: 1}();

        // withdrawAll (first time) - reference: balance becomes 0; bug: balance becomes 2
        vm.prank(user);
        c.withdrawAll();

        // second withdrawAll attempt
        bool ok;
        vm.prank(user);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // In reference (correct), balance is 0, credit is 0, so withdrawAll does nothing (no revert)
        // wait, the reference: after first withdrawal, balance = 0, credit = 0, second withdrawal does nothing, no revert => ok = true
        // The bug: after first withdrawal, balance = 2, credit = 0, second withdrawal: oCredit = 0, so does nothing => ok = true
        // That's the same. Let me think again.
        // The difference: after deposit and one withdrawal, reference balance=0, bug balance=2
        // If another user deposits and tries to withdraw, the bug will cause a different behavior.
        // Let's use a second user to expose the difference.

        address user2 = address(0x456);
        vm.deal(user2, 10 ether);

        // user2 deposits 1 wei
        vm.prank(user2);
        c.deposit{value: 1}();

        // user2 tries to withdrawAll
        vm.prank(user2);
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Reference: balance after user1 withdrawal = 0, then user2 deposit 1 => balance=1, credit[user2]=1
        // Withdrawal: balance -= 1 => balance=0, send 1 wei, credit[user2]=0 -> success, ok=true
        // Bug: balance after user1 withdrawal = 2, then user2 deposit 1 => balance=3, credit[user2]=1
        // Withdrawal: balance += 1 => balance=4, send 1 wei, credit[user2]=0 -> success, ok=true (not diverging)
        // Hmm, need a scenario where the bug causes revert on withdrawal.
        // What if user1 withdraws twice? With bug, first withdraw: balance 1 -> 2, credit 1 -> 0, sends 1 wei
        // Second withdraw: oCredit=0, does nothing. No revert. With reference: first withdraw: balance 1 -> 0, sends 1, credit 0; second: does nothing. Both ok=true.
        // The revert happens only if balance underflows: reference subtracts, needs balance >= oCredit.
        // In bug balance adds, so never underflow from subtraction.
        // But the bug could cause a revert on the call if there's not enough Ether? No, it uses oCredit from msg.sender.
        // Actually the revert in bug can come from the require(callResult) if the call fails, but that's same as reference.
        // Let's examine: bug subtracts nothing, only adds, so balance never underflows. The only revert is from failed call, same as reference.
        // But the test requires a difference: maybe the bug causes a different balance that allows a withdrawal that reference would revert? 
        // Reference: if balance < oCredit, then balance -= oCredit would underflow, causing revert. 
        // But in the code, balance is updated before the call, so if balance < oCredit, the subtraction underflows and reverts.
        // In the bug, balance += oCredit, so never underflow. 
        // So we need a scenario where reference reverts due to underflow, but bug succeeds.
        // This can happen if there's a prior withdrawal that reduced balance incorrectly? Let's try:
        // User A deposits 2 wei. Then user A withdrawAll: reference: balance 2 -> 0, sends 2. Bug: balance 2 -> 4, sends 2.
        // Now user A tries again: reference oCredit = 0, does nothing. Bug: oCredit = 0, does nothing. Both ok.
        // We need a second user who deposits after the first withdrawal, then tries to withdraw more than balance?
        // But the withdrawal amount is exactly their credit, and balance may be less than their credit if bug inflated balance?
        // In bug, after user1 withdrawal, balance = 4, credit[user1]=0. User2 deposits 1: balance=5, credit[user2]=1.
        // User2 withdraws: balance += 1 => 6, sends 1, ok.
        // No underflow possible because balance is always >= credit in reference? Actually in reference, balance can be less than credit if someone else withdraws? 
        // The contract doesn't prevent that: balance is global, credit per user. If user1 has credit 10 and user2 has credit 1, balance could be 11. 
        // If user1 withdraws 10, balance becomes 1. Then user2 withdraws 1, balance becomes 0, ok. No underflow.
        // The underflow can only happen if there's a bug that inflates credit without corresponding balance? No, deposit adds both, withdrawal subtracts credit and either subtracts (reference) or adds (bug) balance.
        // In reference, after all withdrawals, balance should equal sum of credits of users who haven't withdrawn. So no underflow if contract is used correctly.
        // But the bug: after a withdrawal, balance increases, so it's always >= sum of credits. So no underflow either.
        // So revert from underflow won't happen. Then what observable difference? `address(c).balance` or a getter that shows balance.
        // Since balance is public, we can read c.balance() after a sequence of calls.
        // Let's construct: deposit 2 wei from userA, then userA withdrawAll. Reference: c.balance = 0. Bug: c.balance = 4.
        // Assert: c.balance == 0? Reference passes, bug fails because c.balance = 4.
        // But the problem says the difference is after deposit, withdrawAll behaves differently, not after both.
        // Let me read the instructions again: "P and M differ in this way: after a call to deposit() completes, the value of state variable withdrawAll differs". That seems to say after deposit, the state variable withdrawAll differs? That doesn't make sense because withdrawAll is a function. Probably they mean after a call to deposit(), then calling withdrawAll() changes something differently.
        // Actually, the instruction: "Driven through the public/external entry deposit(), P and M differ in this way: after a call to deposit(...) completes, the value of state variable withdrawAll differs: P.withdrawAll() != M.withdrawAll()." This is confusing: "the value of state variable withdrawAll" - there is no state variable named withdrawAll; it's a function. Possibly they meant "the value of balance after calling withdrawAll differs". I'll assume the observable difference is the balance variable.
        // So after a deposit and then a withdrawAll, balance is different.
        // So scenario: deposit 1 wei, then withdrawAll. Reference: balance = 0. Bug: balance = 2. Assert c.balance() == 0. Reference passes, bug fails.
        // But the test must be for the reference contract that passes and bug that fails. So I'll assert `assertEq(c.balance(), 0)` or `assertTrue(c.balance() == 0)`.
        // However, the problem says exactly one assertTrue <concrete fact reading c>. Use assertTrue(c.balance() == 0).

        // Let me correct the test:
        vm.deal(address(0x123), 1);
        vm.prank(address(0x123));
        c.deposit{value: 1}();
        vm.prank(address(0x123));
        c.withdrawAll();
        assertTrue(c.balance() == 0, "Balance should be 0");
    }
}

